(function(root){
'use strict';
const C=typeof module==='object'&&module.exports?require('./core.js'):root.THCore,clone=value=>JSON.parse(JSON.stringify(value));
function checked(data){const errors=C.validate(data);if(errors.length)throw Error(errors.join('\n'));return data;}
function putJourney(data,record,editedId=''){const next=clone(data),items=next.journeys||[];if(items.some(item=>item.id===record.id&&item.id!==editedId))throw Error('Mã lộ trình đã tồn tại.');const value={id:record.id,title:record.title,description:record.description,category:record.category,articles:[...record.articles]},index=items.findIndex(item=>item.id===editedId);if(index<0)items.push(value);else items[index]=value;next.journeys=items;return checked(next);}
function putTerm(data,record,editedId=''){const next=clone(data),items=next.glossary||[];if(items.some(item=>item.id===record.id&&item.id!==editedId))throw Error('Mã thuật ngữ đã tồn tại.');const value={id:record.id,term:record.term,definition:record.definition,category:record.category,url:record.url},index=items.findIndex(item=>item.id===editedId);if(index<0)items.push(value);else items[index]=value;next.glossary=items;return checked(next);}
function remove(data,kind,id){if(!['journeys','glossary'].includes(kind))throw Error('Bộ nội dung không được hỗ trợ.');const next=clone(data);next[kind]=(next[kind]||[]).filter(item=>item.id!==id);return checked(next);}
function move(items,index,direction){const target=index+direction;if(!Number.isInteger(index)||![-1,1].includes(direction)||index<0||index>=items.length||target<0||target>=items.length)return [...items];const next=[...items];[next[index],next[target]]=[next[target],next[index]];return next;}
function mount(api){
 const $=id=>document.getElementById(id),E=C.escape,jForm=$('journey-form'),tForm=$('term-form');let jId='',tId='',jItems=[],jDirty=false,tDirty=false;
 const field=(form,key)=>form.elements.namedItem(key),value=(form,key)=>field(form,key).value.trim();
 function choices(){const D=api.getData(),options=D.categories.map(c=>'<option value="'+E(c.id)+'">'+E(c.name)+'</option>').join('');for(const id of ['journey-category','edit-term-category']){const select=$(id),prior=select.value;select.innerHTML=options;if(D.categories.some(c=>c.id===prior))select.value=prior;}const picker=$('journey-article-picker'),prior=picker.value;picker.innerHTML=D.articles.map(a=>'<option value="'+E(a.id)+'">'+E(a.title)+'</option>').join('');if(D.articles.some(a=>a.id===prior))picker.value=prior;}
 function order(){const D=api.getData();$('journey-ordered-articles').innerHTML=jItems.map((id,i)=>'<li><span><small>'+String(i+1).padStart(2,'0')+'</small><strong>'+E(D.articles.find(a=>a.id===id)?.title||'Bài không còn: '+id)+'</strong></span><div><button type="button" data-step-up="'+i+'" '+(i===0?'disabled':'')+' aria-label="Đưa bài lên">↑</button><button type="button" data-step-down="'+i+'" '+(i===jItems.length-1?'disabled':'')+' aria-label="Đưa bài xuống">↓</button><button type="button" data-step-remove="'+i+'" aria-label="Bỏ bài khỏi lộ trình">Bỏ</button></div></li>').join('')||'<li class="collection-empty">Chọn ít nhất một bài cho lộ trình này.</li>';$('journey-order-count').textContent=jItems.length+' bài theo thứ tự bạn chọn';}
 function fillJourney(record){jForm.reset();jId=record?.id||'';for(const key of ['id','title','description'])field(jForm,key).value=record?.[key]||'';field(jForm,'category').value=record?.category||api.getData().categories[0].id;jItems=[...(record?.articles||[])];jDirty=false;$('journey-delete').hidden=!jId;$('journey-status').textContent='';order();}
 function fillTerm(record){tForm.reset();tId=record?.id||'';for(const key of ['id','term','definition','url'])field(tForm,key).value=record?.[key]||'';field(tForm,'category').value=record?.category||api.getData().categories[0].id;tDirty=false;$('term-delete').hidden=!tId;$('term-edit-status').textContent='';}
 function render(){const D=api.getData();choices();$('journey-editor-list').innerHTML=(D.journeys||[]).map(j=>'<div class="collection-row"><div><strong>'+E(j.title)+'</strong><small>'+j.articles.length+' bài · #'+E(j.id)+'</small></div><button type="button" class="text-button" data-edit-journey="'+E(j.id)+'">Chỉnh sửa ↗</button></div>').join('')||'<p class="collection-empty">Chưa có lộ trình. Tạo một mạch đọc từ các bài đang có.</p>';const query=C.normalize($('term-editor-query').value);const terms=(D.glossary||[]).filter(t=>!query||C.normalize(t.term+' '+t.definition).includes(query));$('term-editor-list').innerHTML=terms.map(t=>'<div class="collection-row"><div><strong>'+E(t.term)+'</strong><small>#'+E(t.id)+' · '+E(D.categories.find(c=>c.id===t.category)?.short||'Thuật ngữ')+'</small></div><button type="button" class="text-button" data-edit-term="'+E(t.id)+'">Chỉnh sửa ↗</button></div>').join('')||'<p class="collection-empty">Chưa có thuật ngữ phù hợp.</p>';$('term-editor-count').textContent=terms.length+' / '+(D.glossary||[]).length+' thuật ngữ';if(!jDirty)fillJourney((D.journeys||[]).find(j=>j.id===jId));else order();if(!tDirty)fillTerm((D.glossary||[]).find(t=>t.id===tId));}
 jForm.addEventListener('input',()=>{jDirty=true;$('journey-status').textContent='Có thay đổi chưa lưu.';});tForm.addEventListener('input',()=>{tDirty=true;$('term-edit-status').textContent='Có thay đổi chưa lưu.';});
 $('journey-editor-list').addEventListener('click',e=>{const button=e.target.closest('[data-edit-journey]');if(!button)return;if(jDirty&&!root.confirm('Bỏ thay đổi chưa lưu của lộ trình đang nhập?'))return;fillJourney(api.getData().journeys.find(j=>j.id===button.dataset.editJourney));$('journey-title').focus();});
 $('term-editor-list').addEventListener('click',e=>{const button=e.target.closest('[data-edit-term]');if(!button)return;if(tDirty&&!root.confirm('Bỏ thay đổi chưa lưu của thuật ngữ đang nhập?'))return;fillTerm(api.getData().glossary.find(t=>t.id===button.dataset.editTerm));$('edit-term-name').focus();});
 $('new-journey').addEventListener('click',()=>{if(jDirty&&!root.confirm('Bỏ thay đổi lộ trình chưa lưu để tạo mới?'))return;fillJourney();$('journey-title').focus();});$('new-term').addEventListener('click',()=>{if(tDirty&&!root.confirm('Bỏ thay đổi thuật ngữ chưa lưu để tạo mới?'))return;fillTerm();$('edit-term-name').focus();});
 $('journey-add-article').addEventListener('click',()=>{const id=$('journey-article-picker').value;if(!api.getData().articles.some(a=>a.id===id)||jItems.includes(id)){$('journey-status').textContent='Bài này đã có trong lộ trình, hoặc chưa hợp lệ.';return;}jItems.push(id);jDirty=true;order();$('journey-status').textContent='Đã thêm bài vào phần đang nhập. Nhấn Lưu để giữ.';});
 $('journey-ordered-articles').addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;const before=jItems;if(button.dataset.stepRemove!==undefined)jItems=jItems.filter((_,i)=>i!==Number(button.dataset.stepRemove));else if(button.dataset.stepUp!==undefined)jItems=move(jItems,Number(button.dataset.stepUp),-1);else if(button.dataset.stepDown!==undefined)jItems=move(jItems,Number(button.dataset.stepDown),1);if(jItems!==before){jDirty=true;order();const from=Number(button.dataset.stepUp??button.dataset.stepDown??button.dataset.stepRemove),at=button.dataset.stepUp!==undefined?from-1:button.dataset.stepDown!==undefined?from+1:Math.min(from,jItems.length-1);$('journey-ordered-articles').querySelector?.('li:nth-child('+(at+1)+') button:not(:disabled)')?.focus();$('journey-status').textContent='Thứ tự có thay đổi chưa lưu.';}});
 jForm.addEventListener('submit',e=>{e.preventDefault();try{const record={...Object.fromEntries(['id','title','description','category'].map(key=>[key,value(jForm,key)])),articles:jItems};const candidate=putJourney(api.getData(),record,jId);if(api.persist(candidate)){jId=record.id;jDirty=false;render();$('journey-status').textContent='Đã lưu lộ trình trong bản nháp.';api.onStatus('Lộ trình sẽ có trong bản xem trước và ZIP xuất.');}}catch(error){api.onError(error.message);}});
 tForm.addEventListener('submit',e=>{e.preventDefault();try{const record=Object.fromEntries(['id','term','definition','category','url'].map(key=>[key,value(tForm,key)]));if(!C.url(record.url))throw Error('Nguồn thuật ngữ cần là URL HTTPS hợp lệ.');const candidate=putTerm(api.getData(),record,tId);if(api.persist(candidate)){tId=record.id;tDirty=false;render();$('term-edit-status').textContent='Đã lưu thuật ngữ trong bản nháp.';api.onStatus('Thuật ngữ sẽ có trong bản xem trước và ZIP xuất.');}}catch(error){api.onError(error.message);}});
 $('journey-delete').addEventListener('click',()=>{if(!jId||!root.confirm('Xóa lộ trình này và bỏ phần đang nhập? Các cẩm nang được giữ lại.'))return;if(api.persist(remove(api.getData(),'journeys',jId))){jDirty=false;fillJourney();render();api.onStatus('Đã bỏ lộ trình khỏi bản nháp.');}});
 $('term-delete').addEventListener('click',()=>{if(!tId||!root.confirm('Xóa thuật ngữ này và bỏ phần đang nhập? Liên kết đã chia sẻ tới mã này sẽ cần cập nhật.'))return;if(api.persist(remove(api.getData(),'glossary',tId))){tDirty=false;fillTerm();render();api.onStatus('Đã bỏ thuật ngữ khỏi bản nháp.');}});
 $('term-editor-query').addEventListener('input',render);
 function reset(){jDirty=false;tDirty=false;jId='';tId='';render();}
 function savePending(){for(const [form,dirty]of [[jForm,()=>jDirty],[tForm,()=>tDirty]])if(dirty()){if(!form.reportValidity())return false;form.requestSubmit();if(dirty())return false;}return true;}
 reset();return {render,reset,savePending,dirty:()=>jDirty||tDirty,capture:()=>({journey:Object.fromEntries(new FormData(jForm)),articles:[...jItems],term:Object.fromEntries(new FormData(tForm))})};
}
const api={putJourney,putTerm,remove,move,mount};if(typeof module==='object'&&module.exports)module.exports=api;else root.THCollections=api;
})(typeof window!=='undefined'?window:globalThis);
